<style>
    .fi-header{display:none!important}.orion-bank-inner,.orion-bank-inner *{box-sizing:border-box;font-family:'Cairo',sans-serif}.orion-bank-inner{--bi-panel:#0c1728;--bi-border:#21324d;--bi-soft:#17263c;--bi-text:#f4f7fb;--bi-muted:#73859f;--bi-purple:#8b5cf6;--bi-green:#34d399;--bi-amber:#fbbf24;--bi-blue:#60a5fa;direction:rtl;color:var(--bi-text)}.bi-hero{display:flex;align-items:center;justify-content:space-between;gap:18px;padding:17px 18px;margin-bottom:13px;border:1px solid #223450;border-radius:14px;background:radial-gradient(circle at 10% 0%,rgba(124,58,237,.17),transparent 34%),linear-gradient(145deg,#0d1829,#091320);box-shadow:0 18px 50px rgba(0,0,0,.12)}.bi-hero-main{display:flex;align-items:center;gap:13px}.bi-icon{width:48px;height:48px;border-radius:13px;display:grid;place-items:center;color:#c4b5fd;background:rgba(124,58,237,.14);border:1px solid rgba(139,92,246,.34)}.bi-icon svg{width:23px;height:23px}.bi-eyebrow{font-size:8px;letter-spacing:1.5px;color:#8c77e8;font-weight:950}.bi-title{font-size:20px;font-weight:950;margin-top:2px}.bi-sub{font-size:9px;color:var(--bi-muted);margin-top:4px;max-width:690px;line-height:1.75}.bi-chips{display:flex;align-items:center;gap:7px;flex-wrap:wrap}.bi-chip{padding:6px 9px;border-radius:999px;font-size:8px;font-weight:900;border:1px solid #2b3c59;background:#0f1b2d;color:#8798b0}.bi-chip.green{color:#5ee2b3;border-color:rgba(52,211,153,.22);background:rgba(52,211,153,.06)}.bi-chip.blue{color:#7ccdf6;border-color:rgba(96,165,250,.22);background:rgba(96,165,250,.06)}.bi-chip.amber{color:#f4c85d;border-color:rgba(251,191,36,.22);background:rgba(251,191,36,.06)}.bi-chip.purple{color:#b8a5ff;border-color:rgba(139,92,246,.24);background:rgba(139,92,246,.07)}.bi-content{border:1px solid #21324d;border-radius:14px;background:linear-gradient(145deg,#0b1524,#091321);overflow:hidden}.orion-bank-inner .fi-section{background:transparent!important;border:0!important;border-radius:0!important;box-shadow:none!important;border-bottom:1px solid #18283f!important}.orion-bank-inner .fi-section:last-child{border-bottom:0!important}.orion-bank-inner .fi-section-header{padding:16px 18px 8px!important}.orion-bank-inner .fi-section-header-heading{font-size:11px!important;font-weight:950!important;color:#edf2f8!important}.orion-bank-inner .fi-section-header-description{font-size:8px!important;color:#667892!important}.orion-bank-inner .fi-section-content{padding:10px 18px 18px!important}.orion-bank-inner .fi-fo-field-wrp-label{color:#8b9bb0!important;font-size:9px!important;font-weight:800!important}.orion-bank-inner .fi-input-wrp{background:#0d192b!important;border-color:#263a59!important;box-shadow:none!important;border-radius:9px!important}.orion-bank-inner .fi-input,.orion-bank-inner textarea,.orion-bank-inner select{color:#dce6f3!important;font-size:10px!important}.orion-bank-inner .fi-fo-field-wrp-helper-text{font-size:8px!important;color:#5f718b!important}.orion-bank-inner .fi-btn{border-radius:9px!important;font-size:9px!important;font-weight:950!important}.orion-bank-inner .fi-btn-color-primary{background:linear-gradient(135deg,#7c3aed,#8b5cf6)!important}.orion-bank-inner .fi-ac-btn-action{font-weight:900!important}@media(max-width:800px){.bi-hero{align-items:flex-start;flex-direction:column}.bi-chips{width:100%}}@media(max-width:560px){.bi-hero-main{align-items:flex-start}.bi-title{font-size:17px}}
</style>
